def solve():
    import sys
    input = sys.stdin.read().splitlines()
    n = int(input[0])
    strings = input[1:n+1]

    from itertools import permutations

    for perm in permutations(strings):
        valid = True
        for i in range(1, n):
            if perm[i-1] not in perm[i]:
                valid = False
                break
        if valid:
            print("YES")
            for s in perm:
                print(s)
            return

    print("NO")

solve()
